begin;
do $$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); p uuid; p2 uuid; c uuid; v text; r jsonb; blocked boolean;
begin
 select version into v from community_private.agreement_releases where current;
 insert into auth.users(id) values(a),(b);
 insert into auth.identities(id,user_id,provider_id,provider,identity_data) values(gen_random_uuid(),a,'hub-test-a','discord','{"name":"Test A"}'),(gen_random_uuid(),b,'hub-test-b','discord','{"name":"Test B"}');
 perform set_config('request.jwt.claim.sub',a::text,true);
 blocked:=false;
 begin perform public.community_hub('create','{"title":"Test post","body":"Body","category":""}'); exception when insufficient_privilege then blocked:=true; end;
 if not blocked then raise exception 'FAIL missing agreement allowed'; end if;
 insert into community_private.member_agreements(user_id,age_group,version) values(a,'adult',v),(b,'adult',v);
 r:=public.community_hub('create','{"title":"Test post","body":"Body ||spoiler|| <script>alert(1)</script>","category":""}');p:=(r->>'id')::uuid;
 perform set_config('request.jwt.claim.sub','',true);
 if jsonb_array_length(public.community_hub('feed',jsonb_build_object('search','Test post')))>0 then raise exception 'FAIL draft leak'; end if;
 blocked:=false;begin perform public.community_hub('post',jsonb_build_object('id',p));exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL draft detail';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.community_hub('publish',jsonb_build_object('id',p));
 perform set_config('request.jwt.claim.sub',b::text,true);
 blocked:=false;begin perform public.community_hub('edit_post',jsonb_build_object('id',p,'title','Hijack','body','bad','category',''));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'FAIL cross-user edit';end if;
 blocked:=false;begin perform public.community_hub('delete_post',jsonb_build_object('id',p));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'FAIL cross-user delete';end if;
 perform public.community_hub('vote',jsonb_build_object('id',p,'value',1));
 update community_private.hub_activity set last_write='epoch' where user_id=b;
 perform public.community_hub('vote',jsonb_build_object('id',p,'value',-1));
 if (select count(*) from community_private.hub_votes where post_id=p)<>1 or (public.community_hub('post',jsonb_build_object('id',p))->>'score')::int<>-1 then raise exception 'FAIL vote switch';end if;
 update community_private.hub_activity set last_write='epoch' where user_id=b;
 c:=(public.community_hub('comment',jsonb_build_object('id',p,'body','Comment'))#>>'{}')::uuid;
 update community_private.hub_activity set last_write='epoch' where user_id=b;
 p2:=(public.community_hub('create','{"title":"Other post","body":"Other","category":"Mission"}')->>'id')::uuid;
 perform public.community_hub('publish',jsonb_build_object('id',p2));
 update community_private.hub_activity set last_write='epoch' where user_id=b;
 blocked:=false;begin perform public.community_hub('comment',jsonb_build_object('id',p2,'body','Wrong thread','parent_id',c));exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL cross-post reply';end if;
 perform public.community_hub('comment',jsonb_build_object('id',p,'body','Reply','parent_id',c));
 if jsonb_array_length(public.community_hub('comments',jsonb_build_object('id',p)))<>2 then raise exception 'FAIL replies';end if;
 perform community_private.withdraw_agreement();
 update community_private.hub_activity set last_write='epoch' where user_id=b;
 blocked:=false;begin perform public.community_hub('comment',jsonb_build_object('id',p,'body','No consent'));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'FAIL withdrawn write';end if;
 perform public.community_hub('vote',jsonb_build_object('id',p,'value',0));
 perform public.community_hub('delete_comment',jsonb_build_object('id',c));
 perform public.community_hub('delete_post',jsonb_build_object('id',p2));
 perform set_config('request.jwt.claim.sub',a::text,true);
 update community_private.hub_activity set last_write='epoch' where user_id=a;
 r:=public.community_hub('create','{"title":"Attachment test","body":"File","category":"Community project","files":[{"filename":"test.txt","mime":"text/plain","bytes":4,"description":""}]}');p2:=(r->>'id')::uuid;
 if not community_private.hub_file_access(r->'files'->0->>'path','upload') then raise exception 'FAIL owner upload';end if;
 blocked:=false;begin perform public.community_hub('publish',jsonb_build_object('id',p2));exception when others then blocked:=true;end;if not blocked then raise exception 'FAIL missing file published';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);
 if community_private.hub_file_access(r->'files'->0->>'path','read') or community_private.hub_file_access(r->'files'->0->>'path','upload') then raise exception 'FAIL private draft file';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.community_hub('cancel_draft',jsonb_build_object('id',p2));
 if not community_private.hub_file_access(r->'files'->0->>'path','delete') then raise exception 'FAIL cleanup owner';end if;
 update community_private.hub_activity set last_write='epoch' where user_id=a;
 blocked:=false;begin perform public.community_hub('create','{"title":"Bad link","body":"Body","category":"","link_text":"Bad","link_url":"javascript:alert(1)"}');exception when check_violation then blocked:=true;end;if not blocked then raise exception 'FAIL unsafe link';end if;
 r:=public.community_hub('create','{"title":"Video test","body":"Clip","category":"PvP","link_text":"Rockstar","link_url":"https://www.rockstargames.com/","files":[{"filename":"clip.mp4","mime":"video/mp4","bytes":20000000,"description":"A test gameplay clip","spoiler":true}]}');p2:=(r->>'id')::uuid;
 if not exists(select 1 from community_private.hub_files where post_id=p2 and spoiler and mime='video/mp4') then raise exception 'FAIL video spoiler';end if;
 perform public.community_hub('cancel_draft',jsonb_build_object('id',p2));
 perform public.community_hub('vote',jsonb_build_object('id',p,'value',1));
 perform public.community_hub('vote',jsonb_build_object('id',p,'value',0));
 if exists(select 1 from community_private.hub_votes where post_id=p and user_id=a) then raise exception 'FAIL immediate vote removal';end if;
 perform public.community_hub('delete_post',jsonb_build_object('id',p));
 if exists(select 1 from community_private.hub_comments where post_id=p) or exists(select 1 from community_private.hub_votes where post_id=p) then raise exception 'FAIL cascade';end if;
end $$;
select 'PASS: agreement, draft privacy, ownership, voting, replies, withdrawal, upload reservations, cleanup and cascades' result;
rollback;

